package com.chatgptcourses.support.service;

import static com.chatgptcourses.account.service.AccountOperations.*;
import static com.chatgptcourses.support.service.SupportWorkTypes.*;
import com.chatgptcourses.operations.service.OperationsStore;
import com.chatgptcourses.shared.http.ApiError;
import com.chatgptcourses.shared.http.EntityTags;
import com.chatgptcourses.shared.http.RevisionPreconditions;
import java.nio.charset.StandardCharsets;
import java.sql.Timestamp;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;

@Service
public class SupportWorkService {
    private final OperationsStore db;private final SupportService support;
    public SupportWorkService(OperationsStore db,SupportService support){this.db=db;this.support=support;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public SupportAssigneePage assignees(UUID actor,int page,int size){db.auth.require(actor,"support.assign");page(page,size);String where=" FROM user_accounts u WHERE u.status='ACTIVE' AND EXISTS(SELECT 1 FROM user_roles ur JOIN role_permissions rp ON rp.role_id=ur.role_id AND rp.revoked_at IS NULL JOIN permissions p ON p.id=rp.permission_id WHERE ur.user_id=u.id AND ur.revoked_at IS NULL AND p.code='support.admin.read')";long total=db.jdbc.queryForObject("SELECT count(*)"+where,Long.class);var items=db.jdbc.query("SELECT u.id,u.display_name"+where+" ORDER BY u.id LIMIT ? OFFSET ?",(r,n)->new SupportAssignee(r.getObject(1,UUID.class),r.getString(2)),size,(long)page*size);return new SupportAssigneePage(items,page,size,total);}
    @Transactional(readOnly=true)
    public SupportAssignmentView assignment(UUID actor,UUID ticket){db.auth.require(actor,"support.admin.read");exists(ticket);return assignmentRow(ticket);}
    @Transactional
    public SupportAssignmentView assign(UUID actor,UUID context,UUID ticket,String ifMatch,String idem,AssignSupport command){db.auth.mutation(actor,context,"support.assign");check(command!=null);text(command.reason(),2000);UUID key=key(idem);byte[] hash=db.hash(Arrays.asList(ticket,command));db.lockTicket(actor,ticket);db.auth.mutation(actor,context,"support.assign");if(db.replay(actor,"SUPPORT_ASSIGN",key,hash)!=null)return assignmentRow(ticket);var current=assignmentRow(ticket);RevisionPreconditions.requireMatch(ifMatch,assignmentTag(current));db.assignee(command.assigneeId(),"support.admin.read");var stamp=db.ticketStamp(ticket);if(current.revision()==0)db.jdbc.update("INSERT INTO support_workspaces(ticket_id,assignee_id,revision,updated_at) VALUES(?,?,1,?)",ticket,command.assigneeId(),stamp);else db.jdbc.update("UPDATE support_workspaces SET assignee_id=?,revision=revision+1,updated_at=? WHERE ticket_id=?",command.assigneeId(),stamp,ticket);db.audit(actor,"SUPPORT_ASSIGN","SUPPORT_TICKET",ticket,"SUPPORT_WORK","SAVED");db.remember(actor,"SUPPORT_ASSIGN",key,hash,"ASSIGNMENT",ticket);return assignmentRow(ticket);}
    @Transactional(readOnly=true)
    public SupportDraftView draft(UUID actor,UUID ticket){db.auth.require(actor,"support.drafts");exists(ticket);return draftRow(actor,ticket);}
    @Transactional
    public SupportDraftView saveDraft(UUID actor,UUID context,UUID ticket,String ifMatch,SaveSupportDraft command){db.auth.mutation(actor,context,"support.drafts");check(command!=null&&command.text()!=null&&command.text().length()<=8000&&command.text().indexOf('\0')<0);db.lockTicket(actor,ticket);db.auth.mutation(actor,context,"support.drafts");var current=draftRow(actor,ticket);RevisionPreconditions.requireMatch(ifMatch,draftTag(current));if(current.text().equals(command.text())&&!"PUBLISHED".equals(current.state()))return current;var stamp=db.ticketStamp(ticket);String state=command.text().isBlank()?"EMPTY":"DRAFT";if(current.revision()==0)db.jdbc.update("INSERT INTO support_reply_drafts(ticket_id,author_id,revision,body,state,updated_at) VALUES(?,?,1,?,?,?)",ticket,actor,command.text(),state,stamp);else db.jdbc.update("UPDATE support_reply_drafts SET body=?,state=?,revision=revision+1,updated_at=? WHERE ticket_id=? AND author_id=?",command.text(),state,stamp,ticket,actor);db.audit(actor,"SUPPORT_DRAFT_SAVE","SUPPORT_TICKET",ticket,"SUPPORT_WORK","SAVED");return draftRow(actor,ticket);}
    @Transactional
    public PublicationResult publishDraft(UUID actor,UUID context,UUID ticket,String ifMatch,String idem,PublishSupportDraft command){db.auth.mutation(actor,context,"support.reply");db.auth.require(actor,"support.drafts");check(command!=null&&command.expectedTicketRevision()>=0);text(command.reason(),2000);UUID key=key(idem);byte[] hash=db.hash(Arrays.asList(ticket,ifMatch,command));db.lockTicket(actor,ticket);db.auth.mutation(actor,context,"support.reply");db.auth.require(actor,"support.drafts");var replay=db.replay(actor,"SUPPORT_PUBLISH",key,hash);if(replay!=null)return new PublicationResult(publication(actor,ticket,replay.id()),false);var current=draftRow(actor,ticket);RevisionPreconditions.requireMatch(ifMatch,draftTag(current));if(!"DRAFT".equals(current.state())||current.text().isBlank())throw error(ApiError.SUPPORT_DRAFT_NOT_PUBLISHABLE);var parent=support.get(actor,ticket,true);if(parent.revision()!=command.expectedTicketRevision())throw error(ApiError.REVISION_CONFLICT);UUID childKey=UUID.nameUUIDFromBytes(("support-publication:"+actor+":"+key).getBytes(StandardCharsets.UTF_8));var sent=support.addMessage(actor,context,ticket,true,SupportService.tag(parent),childKey.toString(),new SupportTypes.AddSupportMessage(current.text(),List.of()));var stamp=db.ticketStamp(ticket);db.jdbc.update("UPDATE support_reply_drafts SET state='PUBLISHED',published_message_id=?,revision=revision+1,updated_at=? WHERE ticket_id=? AND author_id=?",sent.value().message().id(),stamp,ticket,actor);UUID id=UUID.randomUUID();db.jdbc.update("INSERT INTO support_reply_publications(id,ticket_id,author_id,draft_revision,message_id,published_at) VALUES(?,?,?,?,?,?)",id,ticket,actor,current.revision(),sent.value().message().id(),stamp);db.remember(actor,"SUPPORT_PUBLISH",key,hash,"PUBLICATION",id);db.audit(actor,"SUPPORT_DRAFT_PUBLISH","SUPPORT_TICKET",ticket,"SUPPORT_WORK","PUBLISHED");return new PublicationResult(new PublishedSupportReply(sent.value().ticket(),sent.value().message(),draftRow(actor,ticket)),true);}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public InternalNotePage notes(UUID actor,UUID ticket,int page,int size){db.auth.require(actor,"support.internal.read");exists(ticket);page(page,size);long total=db.jdbc.queryForObject("SELECT count(*) FROM support_internal_notes WHERE ticket_id=?",Long.class,ticket);var rows=db.jdbc.query("SELECT * FROM support_internal_notes WHERE ticket_id=? ORDER BY entry_number LIMIT ? OFFSET ?",(r,n)->new InternalNote(r.getObject("id",UUID.class),ticket,r.getObject("author_id",UUID.class),r.getString("body"),instant(r,"created_at")),ticket,size,(long)page*size);return new InternalNotePage(rows,page,size,total);}
    @Transactional
    public NoteResult addNote(UUID actor,UUID context,UUID ticket,String idem,AddInternalNote command){db.auth.mutation(actor,context,"support.internal.write");check(command!=null);text(command.text(),4000);UUID key=key(idem);byte[] hash=db.hash(Arrays.asList(ticket,command));db.lockTicket(actor,ticket);db.auth.mutation(actor,context,"support.internal.write");var replay=db.replay(actor,"SUPPORT_NOTE",key,hash);if(replay!=null)return new NoteResult(noteRow(replay.id()),false);UUID id=UUID.randomUUID();db.jdbc.update("INSERT INTO support_internal_notes(id,ticket_id,author_id,body,entry_number,created_at) SELECT ?,?,?,?,coalesce(max(entry_number),0)+1,? FROM support_internal_notes WHERE ticket_id=?",id,ticket,actor,command.text(),db.ticketStamp(ticket),ticket);db.remember(actor,"SUPPORT_NOTE",key,hash,"INTERNAL_NOTE",id);db.audit(actor,"SUPPORT_NOTE_ADD","SUPPORT_TICKET",ticket,"SUPPORT_WORK","SAVED");return new NoteResult(noteRow(id),true);}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public SupportTimePage times(UUID actor,UUID ticket,int page,int size){db.auth.require(actor,"support.time.read");exists(ticket);page(page,size);long total=db.jdbc.queryForObject("SELECT count(*) FROM support_time_entries WHERE ticket_id=?",Long.class,ticket);var rows=db.jdbc.query("SELECT * FROM support_time_entries WHERE ticket_id=? ORDER BY entry_number LIMIT ? OFFSET ?",(r,n)->new SupportTimeEntry(r.getObject("id",UUID.class),ticket,r.getObject("author_id",UUID.class),r.getInt("minutes"),r.getString("reason"),instant(r,"created_at")),ticket,size,(long)page*size);return new SupportTimePage(rows,page,size,total);}
    @Transactional
    public TimeResult recordTime(UUID actor,UUID context,UUID ticket,String idem,RecordSupportTime command){db.auth.mutation(actor,context,"support.time.write");check(command!=null&&command.minutes()>=0&&command.minutes()<=1440);text(command.reason(),2000);UUID key=key(idem);byte[] hash=db.hash(Arrays.asList(ticket,command));db.lockTicket(actor,ticket);db.auth.mutation(actor,context,"support.time.write");var replay=db.replay(actor,"SUPPORT_TIME",key,hash);if(replay!=null)return new TimeResult(timeRow(replay.id()),false);UUID id=UUID.randomUUID();db.jdbc.update("INSERT INTO support_time_entries(id,ticket_id,author_id,minutes,reason,entry_number,created_at) SELECT ?,?,?,?,?,coalesce(max(entry_number),0)+1,? FROM support_time_entries WHERE ticket_id=?",id,ticket,actor,command.minutes(),command.reason(),db.ticketStamp(ticket),ticket);db.remember(actor,"SUPPORT_TIME",key,hash,"TIME_ENTRY",id);db.audit(actor,"SUPPORT_TIME_ADD","SUPPORT_TICKET",ticket,"SUPPORT_WORK","SAVED");return new TimeResult(timeRow(id),true);}
    private PublishedSupportReply publication(UUID actor,UUID ticket,UUID id){UUID message=db.jdbc.queryForObject("SELECT message_id FROM support_reply_publications WHERE id=? AND ticket_id=? AND author_id=?",UUID.class,id,ticket,actor);return new PublishedSupportReply(support.get(actor,ticket,true),support.messageForOperator(actor,ticket,message),draftRow(actor,ticket));}
    private SupportAssignmentView assignmentRow(UUID ticket){var rows=db.jdbc.query("SELECT * FROM support_workspaces WHERE ticket_id=?",(r,n)->new SupportAssignmentView(ticket,r.getLong("revision"),r.getObject("assignee_id",UUID.class),instant(r,"updated_at")),ticket);return rows.isEmpty()?new SupportAssignmentView(ticket,0,null,null):rows.getFirst();}
    private SupportDraftView draftRow(UUID actor,UUID ticket){var rows=db.jdbc.query("SELECT * FROM support_reply_drafts WHERE ticket_id=? AND author_id=?",(r,n)->new SupportDraftView(ticket,actor,r.getLong("revision"),r.getString("body"),r.getString("state"),r.getObject("published_message_id",UUID.class),instant(r,"updated_at")),ticket,actor);return rows.isEmpty()?new SupportDraftView(ticket,actor,0,"","EMPTY",null,null):rows.getFirst();}
    private InternalNote noteRow(UUID id){return db.jdbc.queryForObject("SELECT * FROM support_internal_notes WHERE id=?",(r,n)->new InternalNote(id,r.getObject("ticket_id",UUID.class),r.getObject("author_id",UUID.class),r.getString("body"),instant(r,"created_at")),id);}
    private SupportTimeEntry timeRow(UUID id){return db.jdbc.queryForObject("SELECT * FROM support_time_entries WHERE id=?",(r,n)->new SupportTimeEntry(id,r.getObject("ticket_id",UUID.class),r.getObject("author_id",UUID.class),r.getInt("minutes"),r.getString("reason"),instant(r,"created_at")),id);}
    private void exists(UUID ticket){if(!Boolean.TRUE.equals(db.jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM support_tickets WHERE id=?)",Boolean.class,ticket)))throw error(ApiError.RESOURCE_NOT_FOUND);}
    public static String assignmentTag(SupportAssignmentView value){return EntityTags.forRevision("support-assignment",value.ticketId(),value.revision());}
    public static String draftTag(SupportDraftView value){return "\"support-draft-"+value.ticketId()+"-"+value.authorId()+"-r"+value.revision()+"\"";}
}
